changeSet.sql:
CREATE TABLE public.mentor_owner (
    account_id BIGINT NOT NULL CONSTRAINT mentor_ownerPK PRIMARY KEY,
    created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL
);
ALTER TABLE public.mentor_owner ENABLE ROW LEVEL SECURITY;
CREATE POLICY mentor_owner_owner ON public.mentor_owner TO hephaestus_app
    USING (account_id = public.current_owner_account())
    WITH CHECK (account_id = public.current_owner_account());
